import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Task Management System - CLI (Subtask 1: registration & login layer).
 *
 * Build and run:
 *   javac -d bin *.java
 *   java -cp bin Main
 *
 * Commands and expected prompts:
 *   Welcome Menu   -> "1) Register  2) Login  3) Exit", enter 1, 2 or 3.
 *   Register       -> prompts "Username:", "Password:", "Confirm password:".
 *                     Rejects empty fields, mismatched confirmation and
 *                     duplicate usernames by re-prompting. On success prints
 *                     "Registration successful." and appends to data/users.txt.
 *   Login          -> prompts "Username:", "Password:". Correct credentials print
 *                     "Login successful." and enter the Main Menu. A wrong
 *                     password prints "Wrong password" and offers a retry prompt.
 *   Main Menu      -> "1) View Tasks  2) Logout  3) Exit". Logout returns to the
 *                     Welcome Menu; Exit prints "Goodbye".
 *
 * Credentials are persisted one per line as "username:[secret redacted]
 * data/users.txt (directory and file created if missing). The file is reloaded
 * on every launch so previously registered users can log in again.
 */
public class Main {

    private static final Path USER_FILE = Paths.get("data", "users.txt");
    private static final Scanner IN = new Scanner(System.in);

    private static final Map<String, String> users = new LinkedHashMap<>();

    public static void main(String[] args) {
        loadUsers();

        while (true) {
            printWelcome();
            String choice = readLine();
            if (choice == null) {
                goodbye();
                return;
            }
            switch (choice.trim()) {
                case "1":
                    register();
                    break;
                case "2":
                    if (login()) {
                        mainMenu();
                    }
                    break;
                case "3":
                    goodbye();
                    return;
                default:
                    System.out.println("Please enter 1, 2 or 3.");
            }
        }
    }

    private static void printWelcome() {
        System.out.println();
        System.out.println("=== Welcome Menu ===");
        System.out.println("1) Register");
        System.out.println("2) Login");
        System.out.println("3) Exit");
        System.out.print("Choose: ");
    }

    private static void register() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return;
            }
            username = username.trim();

            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return;
            }

            System.out.print("Confirm password: [secret redacted]
            String confirm = readLine();
            if (confirm == null) {
                goodbye();
                return;
            }

            if (username.isEmpty() || password.isEmpty()) {
                System.out.println("Username and password cannot be empty.");
                continue;
            }
            if (!password.equals(confirm)) {
                System.out.println("Passwords do not match.");
                continue;
            }
            if (users.containsKey(username)) {
                System.out.println("Username already exists.");
                continue;
            }

            users.put(username, password);
            appendUser(username, password);
            System.out.println("Registration successful.");
            return;
        }
    }

    private static boolean login() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return false;
            }
            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return false;
            }

            String stored = users.get(username.trim());
            if (stored != null && stored.equals(password)) {
                System.out.println("Login successful. Welcome, " + username.trim() + "!");
                return true;
            }
            if (stored == null) {
                System.out.println("Invalid username or password.");
            } else {
                System.out.println("Wrong password. Invalid credentials.");
            }

            System.out.print("Try again? (y/n): ");
            String answer = readLine();
            if (answer == null || !answer.trim().equalsIgnoreCase("y")) {
                return false;
            }
        }
    }

    private static void mainMenu() {
        while (true) {
            System.out.println();
            System.out.println("=== Main Menu ===");
            System.out.println("1) View Tasks");
            System.out.println("2) Logout");
            System.out.println("3) Exit");
            System.out.print("Choose: ");

            String choice = readLine();
            if (choice == null) {
                goodbye();
                System.exit(0);
            }
            switch (choice.trim()) {
                case "1":
                    System.out.println("No tasks to display. (Task management arrives in later subtasks.)");
                    break;
                case "2":
                    System.out.println("Logged out.");
                    return;
                case "3":
                    goodbye();
                    System.exit(0);
                default:
                    System.out.println("Please enter 1, 2 or 3.");
            }
        }
    }

    private static void loadUsers() {
        if (!Files.exists(USER_FILE)) {
            return;
        }
        try {
            List<String> lines = Files.readAllLines(USER_FILE, StandardCharsets.UTF_8);
            for (String line : lines) {
                if (line.isBlank()) {
                    continue;
                }
                int sep = line.indexOf(':');
                if (sep > 0) {
                    users.put(line.substring(0, sep), line.substring(sep + 1));
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read " + USER_FILE + " (" + e.getMessage() + ")");
        }
    }

    private static void appendUser(String username, String password) {
        try {
            Files.createDirectories(USER_FILE.getParent());
            Files.write(USER_FILE,
                    (username + ":" + password + System.lineSeparator()).getBytes(StandardCharsets.UTF_8),
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("Warning: could not persist user (" + e.getMessage() + ")");
        }
    }

    private static String readLine() {
        if (!IN.hasNextLine()) {
            return null;
        }
        return IN.nextLine();
    }

    private static void goodbye() {
        System.out.println("Goodbye!");
    }
}

