        String choice = readLine();
        if (choice == null) {
            goodbye();
            System.exit(0);
        }
        switch (choice.trim()) {
            case "1":
                listTasks();
                break;
            case "2":
                addTask();
                break;
            case "3":
                completeTask();
                break;
            case "4":
                deleteTask();
                break;
            case "5":
                System.out.println("Logged out.");
                return;
