                goodbye();
                System.exit(0);
            default:
                System.out.println("Please enter 1-6.");
        }
    }
}

private static void listTasks() {
    List<Task> tasks = loadTasks();
    if (tasks.isEmpty()) {
        System.out.println("No tasks to display.");
        return;
    }
    System.out.println("Tasks for " + currentUser + ":");
    for (Task t : tasks) {
        System.out.println("[" + t.id + "] " + t.title
                + " | description: " + t.description
                + " | timestamp: " + t.timestamp
                + " | status: " + t.status);
    }
}

private static void addTask() {
    System.out.print("Title: ");
    String title = readLine();
    if (title == null) {
        goodbye();
        System.exit(0);
    }
    title = title.trim();
    if (title.isEmpty()) {
        System.out.println("Title cannot be empty.");
        return;
    }
    System.out.print("Description: ");
    String description = readLine();
    if (description == null) {
        goodbye();
        System.exit(0);
    }
    description = description.trim();

    List<Task> tasks = loadTasks();
    int nextId = 1;
    for (Task t : tasks) {
        nextId = Math.max(nextId, t.id + 1);
    }
    Task task = new Task(nextId, title, description,
            LocalDateTime.now().withNano(0).toString(), "Pending");
    tasks.add(task);
    saveTasks(tasks);
    System.out.println("Task " + nextId + " added.");
}

private static void completeTask() {
    System.out.print("Task ID to mark completed: ");
    Integer id = readId();
    if (id == null) {
        return;
    }
    List<Task> tasks = loadTasks();
    for (Task t : tasks) {
        if (t.id == id) {
            t.status = "Completed";
            saveTasks(tasks);
            System.out.println("Task " + id + " marked Completed");
            return;
        }
    }
    System.out.println("Task " + id + " not found.");
}

private static void deleteTask() {
    System.out.print("Task ID to delete: ");
    Integer id = readId();
    if (id == null) {
        return;
    }
    List<Task> tasks = loadTasks();
    for (Task t : tasks) {
        if (t.id == id) {
            tasks.remove(t);
            saveTasks(tasks);
            System.out.println("Task " + id + " deleted");
            return;
        }
    }
    System.out.println("Task " + id + " not found.");
}

private static Integer readId() {
    String line = readLine();
    if (line == null) {
        goodbye();
        System.exit(0);
    }
    try {
        return Integer.parseInt(line.trim());
    } catch (NumberFormatException e) {
        System.out.println("Please enter a numeric task ID.");
        return null;
    }
}

/** Builds the per-user task file path, sanitising characters unsafe for a file name. */
private static Path taskFile() {
    String safe = currentUser.replaceAll("[^A-Za-z0-9_.-]", "_");
    return Paths.get("data", safe + "_tasks.txt");
}

private static List<Task> loadTasks() {
    List<Task> tasks = new ArrayList<>();
    Path file = taskFile();
    if (!Files.exists(file)) {
        return tasks;
    }
    try {
        for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
            if (line.isBlank()) {
                continue;
            }
            String[] parts = line.split("\\|", 5);
            if (parts.length == 5) {
                tasks.add(new Task(Integer.parseInt(parts[0]), parts[1], parts[2],
                        parts[3], parts[4]));
            }
        }
    } catch (IOException | NumberFormatException e) {
        System.out.println("Warning: could not read " + file + " (" + e.getMessage() + ")");
    }
    return tasks;
}

private static void saveTasks(List<Task> tasks) {
    Path file = taskFile();
    StringBuilder sb = new StringBuilder();
    for (Task t : tasks) {
        sb.append(t.id).append('|').append(t.title).append('|').append(t.description)
                .append('|').append(t.timestamp).append('|').append(t.status)
                .append(System.lineSeparator());
    }
    try {
        Files.createDirectories(file.getParent());
        Files.write(file, sb.toString().getBytes(StandardCharsets.UTF_8));
    } catch (IOException e) {
        System.out.println("Warning: could not persist tasks (" + e.getMessage() + ")");
    }
}

