private static final Map<String, String> users = new LinkedHashMap<>();
private static String currentUser;

// Active view state shared by the View Tasks prompt and the Main Menu.
private static String filterKind;   // null, "priority" or "tag"
private static String filterValue;
private static boolean sortByDeadline;

/** One task of the logged-in user. See class comment for the storage format. */
private static class Task {
    int id;
    String title;
    String description;
    String timestamp;
    String status;
    String priority;   // High / Medium / Low (legacy lines default to Low)
    String deadline;   // YYYY-MM-DD, or "" when unset
    String tags;       // comma-separated, or "" when unset

    Task(int id, String title, String description, String timestamp, String status,
         String priority, String deadline, String tags) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.timestamp = timestamp;
        this.status = status;
        this.priority = priority;
        this.deadline = deadline;
        this.tags = tags;
    }

    List<String> tagList() {
        List<String> out = new ArrayList<>();
        for (String tag : tags.split(",")) {
            tag = tag.trim();
            if (!tag.isEmpty()) {
                out.add(tag);
            }
        }
        return out;
    }
}

