/** View Tasks sub-loop: prints the (filtered/sorted) list, then reads commands. */
private static void viewTasks() {
    while (true) {
        displayTasks();
        System.out.print("Command (/filter priority=high | /filter tag=work | /sort deadline | /clear | Enter to return): ");
        String line = readLine();
        if (line == null) {
            goodbye();
            System.exit(0);
        }
        line = line.trim();
        if (line.isEmpty() || line.equalsIgnoreCase("back") || line.equalsIgnoreCase("b")) {
            return;
        }
        if (!taskCommand(line)) {
            System.out.println("Unknown command. Use /filter, /sort, /clear or Enter to return.");
        }
    }
}

/** Applies the active filter and sort, then prints the current user's tasks. */
private static void displayTasks() {
    List<Task> shown = new ArrayList<>();
    for (Task t : loadTasks()) {
        if (filterKindMatching(t)) {
            shown.add(t);
        }
    }
    if (sortByDeadline) {
        // Deadline ascending; tasks without a deadline are ordered last.
        shown.sort((a, b) -> {
            boolean aEmpty = a.deadline.isEmpty();
            boolean bEmpty = b.deadline.isEmpty();
            if (aEmpty && bEmpty) {
                return Integer.compare(a.id, b.id);
            }
            if (aEmpty) {
                return 1;
            }
            if (bEmpty) {
                return -1;
            }
            return a.deadline.compareTo(b.deadline);
        });
    }
    if (shown.isEmpty()) {
        System.out.println("No tasks to display.");
        return;
    }
    System.out.println("Tasks for " + currentUser + ":");
    for (Task t : shown) {
        System.out.println("[" + t.id + "] " + t.title
                + " | description: " + t.description
                + " | timestamp: " + t.timestamp
                + " | status: " + t.status
                + " | priority: " + t.priority
                + " | deadline: " + (t.deadline.isEmpty() ? "(none)" : t.deadline)
                + " | tags: " + (t.tags.isEmpty() ? "(none)" : t.tags));
    }
}

private static boolean filterKindMatching(Task t) {
    if (filterKind == null) {
        return true;
    }
    if (filterKind.equals("priority")) {
        return t.priority.equalsIgnoreCase(filterValue);
    }
    if (filterKind.equals("tag")) {
        for (String tag : t.tagList()) {
            if (tag.equalsIgnoreCase(filterValue)) {
                return true;
            }
        }
        return false;
    }
    return true;
}

/** Parses /filter, /sort and /clear. Returns true if the line was a task command. */
private static boolean taskCommand(String line) {
    String lower = line.trim().toLowerCase();
    if (lower.equals("/clear")) {
        filterKind = null;
        filterValue = null;
        sortByDeadline = false;
        System.out.println("Filters cleared.");
        return true;
    }
    if (lower.startsWith("/filter")) {
        String rest = line.trim().substring("/filter".length()).trim();
        int eq = rest.indexOf('=');
        if (eq <= 0) {
            System.out.println("Usage: /filter priority=high | /filter tag=work");
            return true;
        }
        String key = [secret redacted]
        String value = rest.substring(eq + 1).trim();
        if (key.equals("priority")) {
            filterKind = "priority";
            filterValue = value;
            System.out.println("Filtering by priority=" + value);
        } else if (key.equals("tag")) {
            filterKind = "tag";
            filterValue = value;
            System.out.println("Filtering by tag=" + value);
        } else {
            System.out.println("Unknown filter key: [secret redacted]
        }
        return true;
    }
    if (lower.startsWith("/sort")) {
        String rest = line.trim().substring("/sort".length()).trim().toLowerCase();
        if (rest.equals("deadline")) {
            sortByDeadline = true;
            System.out.println("Sorting by deadline (ascending).");
        } else {
            System.out.println("Usage: /sort deadline");
        }
        return true;
    }
    return false;
}

