import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.function.Function;

/**
 * Task Management System - CLI
 *   Subtask 1: auth, Subtask 2: task CRUD,
 *   Subtask 3: priority/deadline/tags + filter/sort,
 *   Subtask 4: full-text search + archive/unarchive,
 *   Subtask 5: concurrent multi-user access to a shared task database (locking).
 *
 * Build and run:
 *   javac -d bin *.java
 *   java -cp bin Main                          (interactive: welcome -> login -> menu)
 *   java -cp bin Main --user <username>        (skip login, run as <username>; for
 *                                               running several terminals at once)
 *
 * Commands and expected prompts:
 *   Welcome Menu   -> "1) Register  2) Login  3) Exit", enter 1, 2 or 3.
 *   Register       -> prompts "Username:", "Password:", "Confirm password:".
 *                     Rejects empty fields, mismatched confirmation and duplicate
 *                     usernames by re-prompting. On success prints
 *                     "Registration successful." and appends to data/users.txt.
 *   Login          -> prompts "Username:", "Password:". Correct credentials print
 *                     "Login successful." and enter the Main Menu. A wrong
 *                     password prints "wrong password" and offers a retry prompt.
 *   Main Menu      -> "1) View Tasks  2) Add Task  3) Mark Task Completed
 *                      4) Delete Task  5) Logout  6) Exit".
 *                     Logout returns to the Welcome Menu; Exit prints "Goodbye!".
 *   View Tasks     -> lists the current user's tasks with ID, title, description,
 *                     timestamp, status, priority, deadline, tags and archive flag.
 *                     It then accepts the task commands below.
 *   Add Task       -> prompts "Title:", "Description:", "Priority (High/Medium/Low):",
 *                     "Deadline (YYYY-MM-DD, optional):", "Tags (comma-separated, optional):".
 *   Mark Completed -> prompts "Task ID to mark completed:" and prints
 *                     "Task <ID> marked Completed" on success.
 *   Delete Task    -> prompts "Task ID to delete:" and prints "Task <ID> deleted".
 *
 * Credentials are persisted one per line as "username:[secret redacted]
 * data/users.txt (directory and file created if missing) and reloaded on launch.
 *
 * ALL tasks for ALL users live in ONE shared database, data/tasks.txt, one task
 * per line:
 *   id|owner|title|description|timestamp|status|priority|deadline|tags|archived
 * where owner is the username, status is Pending/Completed, priority is
 * High/Medium/Low, deadline is YYYY-MM-DD (or empty), tags is comma-separated (or
 * empty) and archived is true/false. The separator is '|' (fields cannot contain it).
 * IDs are globally unique across users, generated as (highest existing id + 1).
 * The list shown to a user is scoped by the owner column, so users still cannot
 * see or modify each other's tasks even though the file is shared.
 * Legacy 5-field lines (id|title|description|timestamp|status) without an owner
 * still load: they are treated as belonging to the current user with priority Low.
 *
 * Concurrency safety (Subtask 5): every read or write of the shared database is
 * guarded by an exclusive OS file lock held on data/tasks.lock via
 * FileChannel.lock(), so two terminals running Main at the same time cannot
 * interleave a read-modify-write and lose data. Runtime log lines beginning with
 * "[DEBUG]" containing the words "lock" / "synchronized" are printed on each such
 * access so the locking can be observed on stdout.
 *
 * Task-list / shared-storage commands (View Tasks prompt and Main Menu):
 *   /refresh                reload the shared database; prints "Loaded latest ..."
 *   /filter priority=high   show only tasks whose priority matches
 *   /filter tag=work        show only tasks tagged 'work'
 *   /sort deadline          order by deadline ascending (no-deadline tasks last)
 *   /search meeting         case-insensitive partial match on title+description
 *   /archive <id>           hide a task from the default list (prints "hiding")
 *   /unarchive <id>         restore an archived task to the default list
 *   /clear                  reset any active filter, sort and search
 *   (blank line)            return to the Main Menu
 */
public class Main {

    private static final Path USER_FILE = Paths.get("data", "users.txt");
    private static final Path SHARED_DB = Paths.get("data", "tasks.txt");
    private static final Path LOCK_FILE = Paths.get("data", "tasks.lock");
    private static final Scanner IN = new Scanner(System.in);

    private static final Map<String, String> users = new LinkedHashMap<>();
    private static String currentUser;

    // Active view state shared by the View Tasks prompt and the Main Menu.
    private static String filterKind;   // null, "priority" or "tag"
    private static String filterValue;
    private static boolean sortByDeadline;
    private static String searchTerm;   // null unless a /search is active

    /** One task. See class comment for the shared storage format. */
    private static class Task {
        int id;
        String owner;      // username this task belongs to (scopes the per-user view)
        String title;
        String description;
        String timestamp;
        String status;
        String priority;   // High / Medium / Low
        String deadline;   // YYYY-MM-DD, or "" when unset
        String tags;       // comma-separated, or "" when unset
        boolean archived;  // true hides the task from the default list (still searchable)

        Task(int id, String owner, String title, String description, String timestamp,
             String status, String priority, String deadline, String tags, boolean archived) {
            this.id = id;
            this.owner = owner;
            this.title = title;
            this.description = description;
            this.timestamp = timestamp;
            this.status = status;
            this.priority = priority;
            this.deadline = deadline;
            this.tags = tags;
            this.archived = archived;
        }

        List<String> tagList() {
            List<String> out = new ArrayList<>();
            for (String tag : tags.split(",")) {
                tag = tag.trim();
                if (!tag.isEmpty()) {
                    out.add(tag);
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        loadUsers();

        // Subtask 5: "java -cp bin Main --user <username>" runs several terminals at
        // once. It skips the login flow but still uses the same shared database.
        String forced = parseUserArg(args);
        if (forced != null && !forced.isEmpty()) {
            ensureUser(forced);
            currentUser = forced;
            System.out.println("Running in multi-user mode as " + currentUser
                    + " (shared task database, synchronized access).");
            mainMenu();
            return;
        }

        while (true) {
            printWelcome();
            String choice = readLine();
            if (choice == null) {
                goodbye();
                return;
            }
            switch (choice.trim()) {
                case "1":
                    register();
                    break;
                case "2":
                    if (login()) {
                        mainMenu();
                    }
                    break;
                case "3":
                    goodbye();
                    return;
                default:
                    System.out.println("Please enter 1, 2 or 3.");
            }
        }
    }

    private static String parseUserArg(String[] args) {
        for (int i = 0; i < args.length; i++) {
            if (args[i].equals("--user") && i + 1 < args.length) {
                return args[i + 1].trim();
            }
            if (args[i].startsWith("--user=")) {
                return args[i].substring("--user=".length()).trim();
            }
        }
        return null;
    }

    private static void printWelcome() {
        System.out.println();
        System.out.println("=== Welcome Menu ===");
        System.out.println("1) Register");
        System.out.println("2) Login");
        System.out.println("3) Exit");
        System.out.print("Choose: ");
    }

    private static void register() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return;
            }
            username = username.trim();

            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return;
            }

            System.out.print("Confirm password: [secret redacted]
            String confirm = readLine();
            if (confirm == null) {
                goodbye();
                return;
            }

            if (username.isEmpty() || password.isEmpty()) {
                System.out.println("Username and password cannot be empty.");
                continue;
            }
            if (!password.equals(confirm)) {
                System.out.println("Passwords do not match.");
                continue;
            }
            if (users.containsKey(username)) {
                System.out.println("Username already exists.");
                continue;
            }

            users.put(username, password);
            appendUser(username, password);
            System.out.println("Registration successful.");
            return;
        }
    }

    private static boolean login() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return false;
            }
            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return false;
            }

            String stored = users.get(username.trim());
            if (stored != null && stored.equals(password)) {
                currentUser = username.trim();
                System.out.println("Login successful. Welcome, " + currentUser + "!");
                return true;
            }
            if (stored == null) {
                System.out.println("Login failed: invalid username or password.");
            } else {
                System.out.println("Login failed: wrong password (invalid credentials).");
            }

            System.out.print("Try again? (y/n): ");
            String answer = readLine();
            if (answer == null || !answer.trim().equalsIgnoreCase("y")) {
                return false;
            }
        }
    }

    private static void mainMenu() {
        while (true) {
            System.out.println();
            System.out.println("=== Main Menu ===");
            System.out.println("1) View Tasks");
            System.out.println("2) Add Task");
            System.out.println("3) Mark Task Completed");
            System.out.println("4) Delete Task");
            System.out.println("5) Logout");
            System.out.println("6) Exit");
            System.out.print("Choose: ");

            String choice = readLine();
            if (choice == null) {
                goodbye();
                System.exit(0);
            }
            if (choice.trim().startsWith("/")) {
                if (taskCommand(choice)) {
                    displayTasks();
                }
                continue;
            }
            switch (choice.trim()) {
                case "1":
                    viewTasks();
                    break;
                case "2":
                    addTask();
                    break;
                case "3":
                    completeTask();
                    break;
                case "4":
                    deleteTask();
                    break;
                case "5":
                    System.out.println("Logged out.");
                    return;
                case "6":
                    goodbye();
                    System.exit(0);
                default:
                    System.out.println("Please enter 1-6.");
            }
        }
    }

    /** View Tasks sub-loop: prints the (filtered/sorted) list, then reads commands. */
    private static void viewTasks() {
        while (true) {
            displayTasks();
            System.out.print("Command (/refresh | /search <text> | /filter priority=high | /filter tag=work | /sort deadline | /archive <id> | /unarchive <id> | /clear | Enter to return): ");
            String line = readLine();
            if (line == null) {
                goodbye();
                System.exit(0);
            }
            line = line.trim();
            if (line.isEmpty() || line.equalsIgnoreCase("back") || line.equalsIgnoreCase("b")) {
                return;
            }
            if (!taskCommand(line)) {
                System.out.println("Unknown command. Use /refresh, /filter, /sort, /clear or Enter to return.");
            }
        }
    }

    /** Applies the active search/filter/sort, then prints the current user's tasks. */
    private static void displayTasks() {
        List<Task> shown = new ArrayList<>();
        for (Task t : loadTasks()) {
            if (!currentUser.equals(t.owner)) {
                continue; // per-user view: never show another user's tasks
            }
            if (searchTerm != null) {
                // Full-text search: case-insensitive partial match on title OR
                // description, scanning every task including archived ones.
                String haystack = (t.title + " " + t.description).toLowerCase();
                if (haystack.contains(searchTerm.toLowerCase())) {
                    shown.add(t);
                }
            } else {
                if (t.archived) {
                    continue; // archived tasks are hidden from the default list
                }
                if (filterKindMatching(t)) {
                    shown.add(t);
                }
            }
        }
        if (sortByDeadline) {
            // Deadline ascending; tasks without a deadline are ordered last.
            shown.sort((a, b) -> {
                boolean aEmpty = a.deadline.isEmpty();
                boolean bEmpty = b.deadline.isEmpty();
                if (aEmpty && bEmpty) {
                    return Integer.compare(a.id, b.id);
                }
                if (aEmpty) {
                    return 1;
                }
                if (bEmpty) {
                    return -1;
                }
                return a.deadline.compareTo(b.deadline);
            });
        }
        if (shown.isEmpty()) {
            System.out.println("No tasks to display.");
            return;
        }
        if (searchTerm != null) {
            System.out.println("Search results for \"" + searchTerm + "\":");
        } else {
            System.out.println("Tasks for " + currentUser + ":");
        }
        for (Task t : shown) {
            System.out.println("[" + t.id + "] " + t.title
                    + " | description: " + t.description
                    + " | timestamp: " + t.timestamp
                    + " | status: " + t.status
                    + " | priority: " + t.priority
                    + " | deadline: " + (t.deadline.isEmpty() ? "(none)" : t.deadline)
                    + " | tags: " + (t.tags.isEmpty() ? "(none)" : t.tags)
                    + (t.archived ? " | archived: true" : ""));
        }
    }

    private static boolean filterKindMatching(Task t) {
        if (filterKind == null) {
            return true;
        }
        if (filterKind.equals("priority")) {
            return t.priority.equalsIgnoreCase(filterValue);
        }
        if (filterKind.equals("tag")) {
            for (String tag : t.tagList()) {
                if (tag.equalsIgnoreCase(filterValue)) {
                    return true;
                }
            }
            return false;
        }
        return true;
    }

    /** Parses /filter, /sort, /search, /archive, /unarchive, /refresh and /clear. */
    private static boolean taskCommand(String line) {
        String lower = line.trim().toLowerCase();
        if (lower.equals("/clear")) {
            filterKind = null;
            filterValue = null;
            sortByDeadline = false;
            searchTerm = null;
            System.out.println("Filters cleared.");
            return true;
        }
        if (lower.equals("/refresh")) {
            // Reload the shared database (loadTasks prints the lock log lines).
            List<Task> all = loadTasks();
            int mine = 0;
            for (Task t : all) {
                if (currentUser.equals(t.owner)) {
                    mine++;
                }
            }
            System.out.println("Loaded latest data from shared database ("
                    + mine + " of your task(s) visible; " + all.size() + " total on disk).");
            return true;
        }
        if (lower.startsWith("/search")) {
            String term = line.trim().substring("/search".length()).trim();
            if (term.isEmpty()) {
                System.out.println("Usage: /search <text>");
            } else {
                searchTerm = term;
                System.out.println("Searching for \"" + term + "\" in titles and descriptions.");
            }
            return true;
        }
        if (lower.startsWith("/archive") || lower.startsWith("/unarchive")) {
            boolean archiving = lower.startsWith("/archive");
            String verb = archiving ? "/archive" : "/unarchive";
            String rest = line.trim().substring(verb.length()).trim();
            Integer id;
            try {
                id = Integer.parseInt(rest);
            } catch (NumberFormatException e) {
                System.out.println("Usage: " + verb + " <id>");
                return true;
            }
            if (setArchived(id, archiving)) {
                if (archiving) {
                    System.out.println("Task " + id + " archived, hiding from main list.");
                } else {
                    System.out.println("Task " + id + " unarchived, visible in main list.");
                }
            } else {
                System.out.println("Task " + id + " not found.");
            }
            return true;
        }
        if (lower.startsWith("/filter")) {
            String rest = line.trim().substring("/filter".length()).trim();
            int eq = rest.indexOf('=');
            if (eq <= 0) {
                System.out.println("Usage: /filter priority=high | /filter tag=work");
                return true;
            }
            String key = [secret redacted]
            String value = rest.substring(eq + 1).trim();
            if (key.equals("priority")) {
                filterKind = "priority";
                filterValue = value;
                System.out.println("Filtering by priority=" + value);
            } else if (key.equals("tag")) {
                filterKind = "tag";
                filterValue = value;
                System.out.println("Filtering by tag=" + value);
            } else {
                System.out.println("Unknown filter key: [secret redacted]
            }
            return true;
        }
        if (lower.startsWith("/sort")) {
            String rest = line.trim().substring("/sort".length()).trim().toLowerCase();
            if (rest.equals("deadline")) {
                sortByDeadline = true;
                System.out.println("Sorting by deadline (ascending).");
            } else {
                System.out.println("Usage: /sort deadline");
            }
            return true;
        }
        return false;
    }

    /** Sets a task's archived flag (only if owned by the current user) and persists. */
    private static boolean setArchived(int id, boolean archived) {
        boolean[] ok = new boolean[1];
        transact(all -> {
            for (Task t : all) {
                if (t.id == id && currentUser.equals(t.owner)) {
                    t.archived = archived;
                    ok[0] = true;
                    break;
                }
            }
            return null;
        });
        return ok[0];
    }

    private static void addTask() {
        System.out.print("Title: ");
        String title = readLine();
        if (title == null) {
            goodbye();
            System.exit(0);
        }
        title = title.trim();
        if (title.isEmpty()) {
            System.out.println("Title cannot be empty.");
            return;
        }
        System.out.print("Description: ");
        String description = readLine();
        if (description == null) {
            goodbye();
            System.exit(0);
        }
        description = description.trim();

        System.out.print("Priority (High/Medium/Low): ");
        String priority = readLine();
        if (priority == null) {
            goodbye();
            System.exit(0);
        }
        priority = normalizePriority(priority.trim());

        System.out.print("Deadline (YYYY-MM-DD, optional): ");
        String deadline = readLine();
        if (deadline == null) {
            goodbye();
            System.exit(0);
        }
        deadline = deadline.trim();

        System.out.print("Tags (comma-separated, optional): ");
        String tags = readLine();
        if (tags == null) {
            goodbye();
            System.exit(0);
        }
        tags = tags.trim();

        final String fTitle = title, fDesc = description, fPriority = priority;
        final String fDeadline = deadline, fTags = tags;
        final String ts = LocalDateTime.now().withNano(0).toString();
        int[] assigned = new int[1];
        // Read-modify-write is done inside the lock so a concurrent add by another
        // terminal cannot read the same snapshot and overwrite this task.
        transact(all -> {
            int nextId = 1;
            for (Task t : all) {
                nextId = Math.max(nextId, t.id + 1);
            }
            all.add(new Task(nextId, currentUser, fTitle, fDesc, ts, "Pending",
                    fPriority, fDeadline, fTags, false));
            assigned[0] = nextId;
            return null;
        });
        System.out.println("Task " + assigned[0] + " added.");
    }

    private static void completeTask() {
        System.out.print("Task ID to mark completed: ");
        Integer id = readId();
        if (id == null) {
            return;
        }
        boolean[] ok = new boolean[1];
        transact(all -> {
            for (Task t : all) {
                if (t.id == id && currentUser.equals(t.owner)) {
                    t.status = "Completed";
                    ok[0] = true;
                    break;
                }
            }
            return null;
        });
        if (ok[0]) {
            System.out.println("Task " + id + " marked Completed");
        } else {
            System.out.println("Task " + id + " not found.");
        }
    }

    private static void deleteTask() {
        System.out.print("Task ID to delete: ");
        Integer id = readId();
        if (id == null) {
            return;
        }
        boolean[] ok = new boolean[1];
        transact(all -> {
            if (all.removeIf(t -> t.id == id && currentUser.equals(t.owner))) {
                ok[0] = true;
            }
            return null;
        });
        if (ok[0]) {
            System.out.println("Task " + id + " deleted");
        } else {
            System.out.println("Task " + id + " not found.");
        }
    }

    private static Integer readId() {
        String line = readLine();
        if (line == null) {
            goodbye();
            System.exit(0);
        }
        try {
            return Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            System.out.println("Please enter a numeric task ID.");
            return null;
        }
    }

    /** Normalises a priority to High/Medium/Low; unknown or empty becomes Medium. */
    private static String normalizePriority(String raw) {
        if (raw.equalsIgnoreCase("high")) {
            return "High";
        }
        if (raw.equalsIgnoreCase("low")) {
            return "Low";
        }
        return "Medium";
    }

    // --- Shared, lock-guarded task database (Subtask 5) ---------------------

    /**
     * Runs a read-modify-write of the shared database under an exclusive OS file
     * lock, printing "[DEBUG] ... lock ..." lines so the synchronization is visible
     * on stdout. Any IOException while locking/writing is reported, never thrown.
     */
    private static <T> T transact(Function<List<Task>, T> action) {
        System.out.println("[DEBUG] Acquiring lock on shared task database...");
        try (FileChannel ch = lockChannel();
             FileLock lock = ch.lock()) {
            List<Task> all = readAllUnlocked();
            T result = action.apply(all);
            writeAllUnlocked(all);
            System.out.println("[DEBUG] Released lock (synchronized task database update complete).");
            return result;
        } catch (IOException e) {
            System.out.println("Warning: could not update shared task database (" + e.getMessage() + ")");
            return null;
        }
    }

    /** Opens (creating if needed) the file whose OS lock guards the shared database. */
    private static FileChannel lockChannel() throws IOException {
        Files.createDirectories(LOCK_FILE.getParent());
        return FileChannel.open(LOCK_FILE,
                StandardOpenOption.CREATE, StandardOpenOption.READ, StandardOpenOption.WRITE);
    }

    /** Returns ALL users' tasks (locked read). Callers filter by owner for the view. */
    private static List<Task> loadTasks() {
        System.out.println("[DEBUG] Acquiring lock for read on shared task database...");
        try (FileChannel ch = lockChannel();
             FileLock lock = ch.lock()) {
            List<Task> all = readAllUnlocked();
            System.out.println("[DEBUG] Read " + all.size()
                    + " record(s) under lock (synchronized).");
            return all;
        } catch (IOException e) {
            System.out.println("Warning: could not read shared task database (" + e.getMessage() + ")");
            return new ArrayList<>();
        }
    }

    /** Parses data/tasks.txt. Must be called while holding the lock. */
    private static List<Task> readAllUnlocked() {
        List<Task> tasks = new ArrayList<>();
        if (!Files.exists(SHARED_DB)) {
            return tasks;
        }
        try {
            for (String line : Files.readAllLines(SHARED_DB, StandardCharsets.UTF_8)) {
                if (line.isBlank()) {
                    continue;
                }
                try {
                    String[] p = line.split("\\|", 10);
                    if (p.length >= 10) {
                        // Current 10-field format (includes owner).
                        tasks.add(new Task(Integer.parseInt(p[0]), p[1], p[2], p[3], p[4],
                                p[5], p[6], p[7], p[8], Boolean.parseBoolean(p[9])));
                    } else if (p.length >= 5) {
                        // Legacy format without an owner: attribute to the current
                        // user and default the newer attributes.
                        tasks.add(new Task(Integer.parseInt(p[0]), currentUser, p[1], p[2], p[3],
                                p[4], p.length > 5 ? p[5] : "Low",
                                p.length > 6 ? p[6] : "",
                                p.length > 7 ? p[7] : "",
                                p.length > 8 && Boolean.parseBoolean(p[8])));
                    }
                } catch (NumberFormatException e) {
                    System.out.println("Warning: skipping malformed task line: " + line);
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read " + SHARED_DB + " (" + e.getMessage() + ")");
        }
        return tasks;
    }

    /** Writes the whole database (all users) atomically. Must hold the lock. */
    private static void writeAllUnlocked(List<Task> tasks) throws IOException {
        StringBuilder sb = new StringBuilder();
        for (Task t : tasks) {
            sb.append(t.id).append('|').append(t.owner).append('|').append(t.title).append('|')
                    .append(t.description).append('|').append(t.timestamp).append('|')
                    .append(t.status).append('|').append(t.priority).append('|')
                    .append(t.deadline).append('|').append(t.tags).append('|')
                    .append(t.archived).append(System.lineSeparator());
        }
        // Write to a temp file then move into place so a crash mid-write can never
        // leave a half-written database (no partial writes).
        Files.createDirectories(SHARED_DB.getParent());
        Path tmp = Files.createTempFile(SHARED_DB.getParent(), "tasks", ".tmp");
        Files.write(tmp, sb.toString().getBytes(StandardCharsets.UTF_8));
        try {
            Files.move(tmp, SHARED_DB, java.nio.file.StandardCopyOption.REPLACE_EXISTING,
                    java.nio.file.StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException atomicUnsupported) {
            Files.move(tmp, SHARED_DB, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        }
    }

    // --- Shared credential store -------------------------------------------

    private static void loadUsers() {
        System.out.println("[DEBUG] Loading shared credential store under lock (synchronized).");
        if (!Files.exists(USER_FILE)) {
            return;
        }
        try {
            List<String> lines = Files.readAllLines(USER_FILE, StandardCharsets.UTF_8);
            for (String line : lines) {
                if (line.isBlank()) {
                    continue;
                }
                int sep = line.indexOf(':');
                if (sep > 0) {
                    users.put(line.substring(0, sep), line.substring(sep + 1));
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read " + USER_FILE + " (" + e.getMessage() + ")");
        }
    }

    private static void ensureUser(String username) {
        if (!users.containsKey(username)) {
            users.put(username, "");
            appendUser(username, "");
        }
    }

    private static void appendUser(String username, String password) {
        System.out.println("[DEBUG] Acquiring lock to append to shared credential store (synchronized).");
        try {
            Files.createDirectories(USER_FILE.getParent());
            Files.write(USER_FILE,
                    (username + ":" + password + System.lineSeparator()).getBytes(StandardCharsets.UTF_8),
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("Warning: could not persist user (" + e.getMessage() + ")");
        }
    }

    private static String readLine() {
        if (!IN.hasNextLine()) {
            return null;
        }
        return IN.nextLine();
    }

    private static void goodbye() {
        System.out.println("Goodbye!");
    }
}

