import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Task Management System - CLI (Subtask 1: auth, Subtask 2: task CRUD,
 * Subtask 3: priority/deadline/tags + filter/sort,
 * Subtask 4: full-text search + archive/unarchive).
 *
 * Build and run:
 *   javac -d bin *.java
 *   java -cp bin Main
 *
 * Commands and expected prompts:
 *   Welcome Menu   -> "1) Register  2) Login  3) Exit", enter 1, 2 or 3.
 *   Register       -> prompts "Username:", "Password:", "Confirm password:".
 *                     Rejects empty fields, mismatched confirmation and
 *                     duplicate usernames by re-prompting. On success prints
 *                     "Registration successful." and appends to data/users.txt.
 *   Login          -> prompts "Username:", "Password:". Correct credentials print
 *                     "Login successful." and enter the Main Menu. A wrong
 *                     password prints "wrong password" and offers a retry prompt.
 *   Main Menu      -> "1) View Tasks  2) Add Task  3) Mark Task Completed
 *                      4) Delete Task  5) Logout  6) Exit".
 *                     Logout returns to the Welcome Menu; Exit prints "Goodbye!".
 *   View Tasks     -> lists tasks with ID, title, description, timestamp, status,
 *                     priority, deadline and tags, e.g.
 *                     "[1] Buy milk | ... | status: Pending | priority: High |
 *                      deadline: 2026-12-01 | tags: home,shopping".
 *                     It then accepts filter/sort commands (see below).
 *   Add Task       -> prompts "Title:", "Description:", "Priority (High/Medium/Low):",
 *                     "Deadline (YYYY-MM-DD, optional):", "Tags (comma-separated, optional):";
 *                     empty title is rejected, priority defaults to Medium.
 *   Mark Completed -> prompts "Task ID to mark completed:" and prints
 *                     "Task <ID> marked Completed" on success.
 *   Delete Task    -> prompts "Task ID to delete:" and prints "Task <ID> deleted";
 *                     the task no longer appears in the next listing.
 *
 * Credentials are persisted one per line as "username:[secret redacted]
 * data/users.txt (directory and file created if missing). The file is reloaded
 * on every launch so previously registered users can log in again.
 *
 * Tasks are persisted per user in data/<username>_tasks.txt, one task per line:
 *   id|title|description|timestamp|status|priority|deadline|tags|archived
 * where status is Pending/Completed, priority is High/Medium/Low, deadline is
 * YYYY-MM-DD (or empty), tags is a comma-separated list (or empty) and archived
 * is true/false (archived tasks are hidden from the default list but remain
 * searchable).
 * Legacy 5-field lines (id|title|description|timestamp|status) still load:
 * priority defaults to Low, deadline and tags default to empty and archived to false.
 * The separator is '|' (fields cannot contain it).
 * IDs are generated per user as (highest existing id + 1), starting at 1, so
 * they stay unique and stable across restarts. Username path separators are
 * rewritten to '_' before building the file name.
 *
 * Task-list commands (accepted from the View Tasks prompt and at the Main Menu):
 *   /filter priority=high   show only tasks whose priority matches
 *   /filter tag=work        show only tasks tagged 'work'
 *   /sort deadline          order by deadline ascending (no-deadline tasks last)
 *   /search meeting         case-insensitive partial match on title+description;
 *                           searches ALL tasks including archived ones
 *   /archive <id>           hide a task from the default list (prints "hiding")
 *   /unarchive <id>         restore an archived task to the default list
 *   /clear                  reset any active filter, sort and search
 *   (blank line)            return to the Main Menu
 */
public class Main {

    private static final Path USER_FILE = Paths.get("data", "users.txt");
    private static final Scanner IN = new Scanner(System.in);

    private static final Map<String, String> users = new LinkedHashMap<>();
    private static String currentUser;

    // Active view state shared by the View Tasks prompt and the Main Menu.
    private static String filterKind;   // null, "priority" or "tag"
    private static String filterValue;
    private static boolean sortByDeadline;
    private static String searchTerm;   // null unless a /search is active

    /** One task of the logged-in user. See class comment for the storage format. */
    private static class Task {
        int id;
        String title;
        String description;
        String timestamp;
        String status;
        String priority;   // High / Medium / Low (legacy lines default to Low)
        String deadline;   // YYYY-MM-DD, or "" when unset
        String tags;       // comma-separated, or "" when unset
        boolean archived;  // true hides the task from the default list (still searchable)

        Task(int id, String title, String description, String timestamp, String status,
             String priority, String deadline, String tags, boolean archived) {
            this.id = id;
            this.title = title;
            this.description = description;
            this.timestamp = timestamp;
            this.status = status;
            this.priority = priority;
            this.deadline = deadline;
            this.tags = tags;
            this.archived = archived;
        }

        List<String> tagList() {
            List<String> out = new ArrayList<>();
            for (String tag : tags.split(",")) {
                tag = tag.trim();
                if (!tag.isEmpty()) {
                    out.add(tag);
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        loadUsers();

        while (true) {
            printWelcome();
            String choice = readLine();
            if (choice == null) {
                goodbye();
                return;
            }
            switch (choice.trim()) {
                case "1":
                    register();
                    break;
                case "2":
                    if (login()) {
                        mainMenu();
                    }
                    break;
                case "3":
                    goodbye();
                    return;
                default:
                    System.out.println("Please enter 1, 2 or 3.");
            }
        }
    }

    private static void printWelcome() {
        System.out.println();
        System.out.println("=== Welcome Menu ===");
        System.out.println("1) Register");
        System.out.println("2) Login");
        System.out.println("3) Exit");
        System.out.print("Choose: ");
    }

    private static void register() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return;
            }
            username = username.trim();

            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return;
            }

            System.out.print("Confirm password: [secret redacted]
            String confirm = readLine();
            if (confirm == null) {
                goodbye();
                return;
            }

            if (username.isEmpty() || password.isEmpty()) {
                System.out.println("Username and password cannot be empty.");
                continue;
            }
            if (!password.equals(confirm)) {
                System.out.println("Passwords do not match.");
                continue;
            }
            if (users.containsKey(username)) {
                System.out.println("Username already exists.");
                continue;
            }

            users.put(username, password);
            appendUser(username, password);
            System.out.println("Registration successful.");
            return;
        }
    }

    private static boolean login() {
        while (true) {
            System.out.print("Username: ");
            String username = readLine();
            if (username == null) {
                goodbye();
                return false;
            }
            System.out.print("Password: [secret redacted]
            String password = [secret redacted]
            if (password =[secret redacted]
                goodbye();
                return false;
            }

            String stored = users.get(username.trim());
            if (stored != null && stored.equals(password)) {
                currentUser = username.trim();
                System.out.println("Login successful. Welcome, " + currentUser + "!");
                return true;
            }
            if (stored == null) {
                System.out.println("Login failed: invalid username or password.");
            } else {
                System.out.println("Login failed: wrong password (invalid credentials).");
            }

            System.out.print("Try again? (y/n): ");
            String answer = readLine();
            if (answer == null || !answer.trim().equalsIgnoreCase("y")) {
                return false;
            }
        }
    }

    private static void mainMenu() {
        while (true) {
            System.out.println();
            System.out.println("=== Main Menu ===");
            System.out.println("1) View Tasks");
            System.out.println("2) Add Task");
            System.out.println("3) Mark Task Completed");
            System.out.println("4) Delete Task");
            System.out.println("5) Logout");
            System.out.println("6) Exit");
            System.out.print("Choose: ");

            String choice = readLine();
            if (choice == null) {
                goodbye();
                System.exit(0);
            }
            if (choice.trim().startsWith("/")) {
                if (taskCommand(choice)) {
                    displayTasks();
                }
                continue;
            }
            switch (choice.trim()) {
                case "1":
                    viewTasks();
                    break;
                case "2":
                    addTask();
                    break;
                case "3":
                    completeTask();
                    break;
                case "4":
                    deleteTask();
                    break;
                case "5":
                    System.out.println("Logged out.");
                    return;
                case "6":
                    goodbye();
                    System.exit(0);
                default:
                    System.out.println("Please enter 1-6.");
            }
        }
    }

    /** View Tasks sub-loop: prints the (filtered/sorted) list, then reads commands. */
    private static void viewTasks() {
        while (true) {
            displayTasks();
            System.out.print("Command (/search <text> | /filter priority=high | /filter tag=work | /sort deadline | /archive <id> | /unarchive <id> | /clear | Enter to return): ");
            String line = readLine();
            if (line == null) {
                goodbye();
                System.exit(0);
            }
            line = line.trim();
            if (line.isEmpty() || line.equalsIgnoreCase("back") || line.equalsIgnoreCase("b")) {
                return;
            }
            if (!taskCommand(line)) {
                System.out.println("Unknown command. Use /filter, /sort, /clear or Enter to return.");
            }
        }
    }

    /** Applies the active search/filter/sort, then prints the current user's tasks. */
    private static void displayTasks() {
        List<Task> shown = new ArrayList<>();
        for (Task t : loadTasks()) {
            if (searchTerm != null) {
                // Full-text search: case-insensitive partial match on title OR
                // description, scanning every task including archived ones.
                String haystack = (t.title + " " + t.description).toLowerCase();
                if (haystack.contains(searchTerm.toLowerCase())) {
                    shown.add(t);
                }
            } else {
                if (t.archived) {
                    continue; // archived tasks are hidden from the default list
                }
                if (filterKindMatching(t)) {
                    shown.add(t);
                }
            }
        }
        if (sortByDeadline) {
            // Deadline ascending; tasks without a deadline are ordered last.
            shown.sort((a, b) -> {
                boolean aEmpty = a.deadline.isEmpty();
                boolean bEmpty = b.deadline.isEmpty();
                if (aEmpty && bEmpty) {
                    return Integer.compare(a.id, b.id);
                }
                if (aEmpty) {
                    return 1;
                }
                if (bEmpty) {
                    return -1;
                }
                return a.deadline.compareTo(b.deadline);
            });
        }
        if (shown.isEmpty()) {
            System.out.println("No tasks to display.");
            return;
        }
        if (searchTerm != null) {
            System.out.println("Search results for \"" + searchTerm + "\":");
        } else {
            System.out.println("Tasks for " + currentUser + ":");
        }
        for (Task t : shown) {
            System.out.println("[" + t.id + "] " + t.title
                    + " | description: " + t.description
                    + " | timestamp: " + t.timestamp
                    + " | status: " + t.status
                    + " | priority: " + t.priority
                    + " | deadline: " + (t.deadline.isEmpty() ? "(none)" : t.deadline)
                    + " | tags: " + (t.tags.isEmpty() ? "(none)" : t.tags)
                    + (t.archived ? " | archived: true" : ""));
        }
    }

    private static boolean filterKindMatching(Task t) {
        if (filterKind == null) {
            return true;
        }
        if (filterKind.equals("priority")) {
            return t.priority.equalsIgnoreCase(filterValue);
        }
        if (filterKind.equals("tag")) {
            for (String tag : t.tagList()) {
                if (tag.equalsIgnoreCase(filterValue)) {
                    return true;
                }
            }
            return false;
        }
        return true;
    }

    /** Parses /filter, /sort, /search, /archive, /unarchive and /clear. */
    private static boolean taskCommand(String line) {
        String lower = line.trim().toLowerCase();
        if (lower.equals("/clear")) {
            filterKind = null;
            filterValue = null;
            sortByDeadline = false;
            searchTerm = null;
            System.out.println("Filters cleared.");
            return true;
        }
        if (lower.startsWith("/search")) {
            String term = line.trim().substring("/search".length()).trim();
            if (term.isEmpty()) {
                System.out.println("Usage: /search <text>");
            } else {
                searchTerm = term;
                System.out.println("Searching for \"" + term + "\" in titles and descriptions.");
            }
            return true;
        }
        if (lower.startsWith("/archive") || lower.startsWith("/unarchive")) {
            boolean archiving = lower.startsWith("/archive");
            String verb = archiving ? "/archive" : "/unarchive";
            String rest = line.trim().substring(verb.length()).trim();
            Integer id;
            try {
                id = Integer.parseInt(rest);
            } catch (NumberFormatException e) {
                System.out.println("Usage: " + verb + " <id>");
                return true;
            }
            if (setArchived(id, archiving)) {
                if (archiving) {
                    System.out.println("Task " + id + " archived, hiding from main list.");
                } else {
                    System.out.println("Task " + id + " unarchived, visible in main list.");
                }
            } else {
                System.out.println("Task " + id + " not found.");
            }
            return true;
        }
        if (lower.startsWith("/filter")) {
            String rest = line.trim().substring("/filter".length()).trim();
            int eq = rest.indexOf('=');
            if (eq <= 0) {
                System.out.println("Usage: /filter priority=high | /filter tag=work");
                return true;
            }
            String key = [secret redacted]
            String value = rest.substring(eq + 1).trim();
            if (key.equals("priority")) {
                filterKind = "priority";
                filterValue = value;
                System.out.println("Filtering by priority=" + value);
            } else if (key.equals("tag")) {
                filterKind = "tag";
                filterValue = value;
                System.out.println("Filtering by tag=" + value);
            } else {
                System.out.println("Unknown filter key: [secret redacted]
            }
            return true;
        }
        if (lower.startsWith("/sort")) {
            String rest = line.trim().substring("/sort".length()).trim().toLowerCase();
            if (rest.equals("deadline")) {
                sortByDeadline = true;
                System.out.println("Sorting by deadline (ascending).");
            } else {
                System.out.println("Usage: /sort deadline");
            }
            return true;
        }
        return false;
    }

    /** Sets a task's archived flag and persists. Returns false if the id is unknown. */
    private static boolean setArchived(int id, boolean archived) {
        List<Task> tasks = loadTasks();
        for (Task t : tasks) {
            if (t.id == id) {
                t.archived = archived;
                saveTasks(tasks);
                return true;
            }
        }
        return false;
    }

    private static void addTask() {
        System.out.print("Title: ");
        String title = readLine();
        if (title == null) {
            goodbye();
            System.exit(0);
        }
        title = title.trim();
        if (title.isEmpty()) {
            System.out.println("Title cannot be empty.");
            return;
        }
        System.out.print("Description: ");
        String description = readLine();
        if (description == null) {
            goodbye();
            System.exit(0);
        }
        description = description.trim();

        System.out.print("Priority (High/Medium/Low): ");
        String priority = readLine();
        if (priority == null) {
            goodbye();
            System.exit(0);
        }
        priority = normalizePriority(priority.trim());

        System.out.print("Deadline (YYYY-MM-DD, optional): ");
        String deadline = readLine();
        if (deadline == null) {
            goodbye();
            System.exit(0);
        }
        deadline = deadline.trim();

        System.out.print("Tags (comma-separated, optional): ");
        String tags = readLine();
        if (tags == null) {
            goodbye();
            System.exit(0);
        }
        tags = tags.trim();

        List<Task> tasks = loadTasks();
        int nextId = 1;
        for (Task t : tasks) {
            nextId = Math.max(nextId, t.id + 1);
        }
        Task task = new Task(nextId, title, description,
                LocalDateTime.now().withNano(0).toString(), "Pending",
                priority, deadline, tags, false);
        tasks.add(task);
        saveTasks(tasks);
        System.out.println("Task " + nextId + " added.");
    }

    private static void completeTask() {
        System.out.print("Task ID to mark completed: ");
        Integer id = readId();
        if (id == null) {
            return;
        }
        List<Task> tasks = loadTasks();
        for (Task t : tasks) {
            if (t.id == id) {
                t.status = "Completed";
                saveTasks(tasks);
                System.out.println("Task " + id + " marked Completed");
                return;
            }
        }
        System.out.println("Task " + id + " not found.");
    }

    private static void deleteTask() {
        System.out.print("Task ID to delete: ");
        Integer id = readId();
        if (id == null) {
            return;
        }
        List<Task> tasks = loadTasks();
        for (Task t : tasks) {
            if (t.id == id) {
                tasks.remove(t);
                saveTasks(tasks);
                System.out.println("Task " + id + " deleted");
                return;
            }
        }
        System.out.println("Task " + id + " not found.");
    }

    private static Integer readId() {
        String line = readLine();
        if (line == null) {
            goodbye();
            System.exit(0);
        }
        try {
            return Integer.parseInt(line.trim());
        } catch (NumberFormatException e) {
            System.out.println("Please enter a numeric task ID.");
            return null;
        }
    }

    /** Normalises a priority to High/Medium/Low; unknown or empty becomes Medium. */
    private static String normalizePriority(String raw) {
        if (raw.equalsIgnoreCase("high")) {
            return "High";
        }
        if (raw.equalsIgnoreCase("low")) {
            return "Low";
        }
        return "Medium";
    }

    /** Builds the per-user task file path, sanitising characters unsafe for a file name. */
    private static Path taskFile() {
        String safe = currentUser.replaceAll("[^A-Za-z0-9_.-]", "_");
        return Paths.get("data", safe + "_tasks.txt");
    }

    private static List<Task> loadTasks() {
        List<Task> tasks = new ArrayList<>();
        Path file = taskFile();
        if (!Files.exists(file)) {
            return tasks;
        }
        try {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                if (line.isBlank()) {
                    continue;
                }
                // Legacy lines have 5 fields; new lines have 9. Missing trailing
                // fields fall back to defaults so old data keeps loading.
                String[] p = line.split("\\|", 9);
                if (p.length >= 5) {
                    tasks.add(new Task(Integer.parseInt(p[0]), p[1], p[2], p[3], p[4],
                            p.length > 5 ? p[5] : "Low",
                            p.length > 6 ? p[6] : "",
                            p.length > 7 ? p[7] : "",
                            p.length > 8 && Boolean.parseBoolean(p[8])));
                }
            }
        } catch (IOException | NumberFormatException e) {
            System.out.println("Warning: could not read " + file + " (" + e.getMessage() + ")");
        }
        return tasks;
    }

    private static void saveTasks(List<Task> tasks) {
        Path file = taskFile();
        StringBuilder sb = new StringBuilder();
        for (Task t : tasks) {
            sb.append(t.id).append('|').append(t.title).append('|').append(t.description)
                    .append('|').append(t.timestamp).append('|').append(t.status)
                    .append('|').append(t.priority).append('|').append(t.deadline)
                    .append('|').append(t.tags)
                    .append('|').append(t.archived)
                    .append(System.lineSeparator());
        }
        try {
            Files.createDirectories(file.getParent());
            Files.write(file, sb.toString().getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            System.out.println("Warning: could not persist tasks (" + e.getMessage() + ")");
        }
    }

    private static void loadUsers() {
        if (!Files.exists(USER_FILE)) {
            return;
        }
        try {
            List<String> lines = Files.readAllLines(USER_FILE, StandardCharsets.UTF_8);
            for (String line : lines) {
                if (line.isBlank()) {
                    continue;
                }
                int sep = line.indexOf(':');
                if (sep > 0) {
                    users.put(line.substring(0, sep), line.substring(sep + 1));
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read " + USER_FILE + " (" + e.getMessage() + ")");
        }
    }

    private static void appendUser(String username, String password) {
        try {
            Files.createDirectories(USER_FILE.getParent());
            Files.write(USER_FILE,
                    (username + ":" + password + System.lineSeparator()).getBytes(StandardCharsets.UTF_8),
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND);
        } catch (IOException e) {
            System.out.println("Warning: could not persist user (" + e.getMessage() + ")");
        }
    }

    private static String readLine() {
        if (!IN.hasNextLine()) {
            return null;
        }
        return IN.nextLine();
    }

    private static void goodbye() {
        System.out.println("Goodbye!");
    }
}
